// debugTestHandler builds the router for the debug-events tests (the
// playback_events_test newHandler precedent: pairing service + store wired,
// nil store allowed — the handler never reads it).
func debugTestHandler(st *store.Store) http.Handler {
	deps := Deps{AdminToken: adminToken, Pairing: pairing.NewService(st, nil)}
	if st != nil {
		deps.Store = st
	}
	return New(deps)
}

// debugLines returns the captured INFO lines carrying the debug-event
// message (the beaconLines precedent).
func debugLines(buf *strings.Builder) []string {
	var lines []string
	for _, ln := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
		if strings.Contains(ln, `msg="debug event"`) {
			lines = append(lines, ln)
		}
	}
	return lines
}

// wellFormedTrace is a canonical playback-trace payload reused across the
// happy paths.
const wellFormedTrace = `{"kind":"playback-trace","item_id":"itm_unknown","mode":"hls","phase":"trace","code":"decoder_init","detail":"started playback"}`

// TestDebugEventsIngestInfoLine pins the "one event, one INFO line" spec
// scenario (device-telemetry): a well-formed event answers 200 with no body
// and its ENTIRE effect is one structured INFO line — the validated
// per-kind fields plus the UA, never the bearer credential (INV4). A
// capability-snapshot logs no item-scoped keys; a client-role (TV) session
// is accepted like an admin one; the handler never reads the store.
func TestDebugEventsIngestInfoLine(t *testing.T) {
	t.Run("playback_trace_200_one_info_line", func(t *testing.T) {
		buf := captureLogs(t)
		resp := doRequest(t, debugTestHandler(openAPIStore(t)), http.MethodPost, "/api/v1/debug-events", wellFormedTrace, adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		if body := readAll(t, resp); body != "" {
			t.Fatalf("200 carried a body: %q", body)
		}
		lines := debugLines(buf)
		if len(lines) != 1 {
			t.Fatalf("captured %d debug lines, want exactly 1; output:\n%s", len(lines), buf.String())
		}
		for _, field := range []string{
			"kind=playback-trace", "item=itm_unknown", "mode=hls",
			"phase=trace", "code=decoder_init", "ua=",
		} {
			if !strings.Contains(lines[0], field) {
				t.Fatalf("debug line %q lacks %q", lines[0], field)
			}
		}
		if strings.Contains(buf.String(), adminToken) {
			t.Fatal("captured log carries the bearer credential (INV4)")
		}
	})

	// capability-snapshot is not item-scoped (D8): its one line carries the
	// detail payload but NO item/mode/phase/code keys at all.
	t.Run("capability_snapshot_line_not_item_scoped", func(t *testing.T) {
		buf := captureLogs(t)
		body := `{"kind":"capability-snapshot","detail":"model= shielding= api=35 media3=1.4 decoders=[hevc,avc]"}`
		resp := doRequest(t, debugTestHandler(openAPIStore(t)), http.MethodPost, "/api/v1/debug-events", body, adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lines := debugLines(buf)
		if len(lines) != 1 {
			t.Fatalf("captured %d debug lines, want 1", len(lines))
		}
		for _, field := range []string{"kind=capability-snapshot", "detail=", "decoders=[hevc,avc]"} {
			if !strings.Contains(lines[0], field) {
				t.Fatalf("debug line %q lacks %q", lines[0], field)
			}
		}
		for _, banned := range []string{"item=", "mode=", "phase=", "code="} {
			if strings.Contains(lines[0], banned) {
				t.Fatalf("capability-snapshot line %q carries item-scoped key %q", lines[0], banned)
			}
		}
	})

	// The route is client-agnostic (browse group): a pairing-minted
	// client-role session (the TV's voice) is accepted like an admin one.
	t.Run("client_role_accepted", func(t *testing.T) {
		buf := captureLogs(t)
		h := debugTestHandler(openAPIStore(t))
		client := mintClientToken(t, h)
		resp := doRequest(t, h, http.MethodPost, "/api/v1/debug-events", wellFormedTrace, client)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("client-role status = %d, want 200", resp.StatusCode)
		}
		if lines := debugLines(buf); len(lines) != 1 {
			t.Fatalf("captured %d debug lines, want 1", len(lines))
		}
	})
}

// TestDebugEventsVocab400 pins the two malformed-vocabulary spec scenarios:
// an unknown kind value → 400 bad_request, and missing per-kind required
// fields → 400 bad_request — nothing logged, no budget consumed.
func TestDebugEventsVocab400(t *testing.T) {
	buf := captureLogs(t)
	h := debugTestHandler(openAPIStore(t))
	cases := []struct {
		name string
		body string
	}{
		// Unknown kind — including the RESERVED `crash`, which must never
		// be an accepted value (ACRA deferred).
		{"unknown_kind", `{"kind":"crash-report","item_id":"i","code":"c"}`},
		{"reserved_crash_rejected", `{"kind":"crash","item_id":"i","mode":"hls","phase":"crash","code":"c","detail":"d"}`},
		{"empty_kind", `{"kind":"","item_id":"i","mode":"hls","phase":"trace","code":"c"}`},
		// playback-trace per-kind required fields: item_id + mode + phase="trace" + code.
		{"trace_missing_item", `{"kind":"playback-trace","mode":"hls","phase":"trace","code":"c"}`},
		{"trace_missing_code", `{"kind":"playback-trace","item_id":"i","mode":"hls","phase":"trace"}`},
		{"trace_wrong_mode", `{"kind":"playback-trace","item_id":"i","mode":"dash","phase":"trace","code":"c"}`},
		{"trace_wrong_phase", `{"kind":"playback-trace","item_id":"i","mode":"hls","phase":"video-error","code":"c"}`},
		{"trace_missing_phase", `{"kind":"playback-trace","item_id":"i","mode":"hls","code":"c"}`},
		// capability-snapshot: detail required, item-scoped fields forbidden.
		{"snapshot_missing_detail", `{"kind":"capability-snapshot"}`},
		{"snapshot_with_item", `{"kind":"capability-snapshot","item_id":"i","detail":"d"}`},
		{"snapshot_with_mode_phase", `{"kind":"capability-snapshot","mode":"hls","phase":"trace","detail":"d"}`},
		// fatal|video-error|stalled mirror the beacon five-field shape.
		{"fatal_missing_detail", `{"kind":"fatal","item_id":"i","mode":"hls","phase":"fatal","code":"c"}`},
		{"fatal_phase_mismatch", `{"kind":"fatal","item_id":"i","mode":"hls","phase":"stalled","code":"c","detail":"d"}`},
		{"video_error_missing_item", `{"kind":"video-error","mode":"direct","phase":"video-error","code":"c","detail":"d"}`},
		{"stalled_missing_code", `{"kind":"stalled","item_id":"i","mode":"direct","phase":"stalled","detail":"d"}`},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			resp := doRequest(t, h, http.MethodPost, "/api/v1/debug-events", tc.body, adminToken)
			if resp.StatusCode != http.StatusBadRequest {
				t.Fatalf("status = %d, want 400", resp.StatusCode)
			}
			if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
				t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
			}
		})
	}
	if lines := debugLines(buf); len(lines) != 0 {
		t.Fatalf("rejected events logged %d lines, want 0:\n%s", len(lines), buf.String())
	}
}

// TestDebugEventsRateLimitedSilent pins the "flood is capped silently" spec
// scenario: exactly the per-IP window budget is admitted, further events
// answer 429 rate_limited and log NOTHING — and no captured line ever
// carries the bearer credential (INV4).
func TestDebugEventsRateLimitedSilent(t *testing.T) {
	buf := captureLogs(t)
	h := debugTestHandler(openAPIStore(t))
	accepted := 0
	for i := 0; i <= beaconBurst+2; i++ {
		resp := doRequest(t, h, http.MethodPost, "/api/v1/debug-events", wellFormedTrace, adminToken)
		switch {
		case i < beaconBurst:
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("event %d status = %d, want 200", i, resp.StatusCode)
			}
			accepted++
		default:
			if resp.StatusCode != http.StatusTooManyRequests {
				t.Fatalf("event %d (over limit) status = %d, want 429", i, resp.StatusCode)
			}
			if eb := decodeError(t, resp); eb.Error.Code != "rate_limited" {
				t.Fatalf("over-limit error code = %q, want rate_limited", eb.Error.Code)
			}
		}
	}
	if lines := debugLines(buf); len(lines) != accepted {
		t.Fatalf("captured %d debug lines for %d accepted, rejected ones must log nothing:\n%s",
			len(lines), accepted, buf.String())
	}
	if strings.Contains(buf.String(), adminToken) {
		t.Fatal("captured log carries the bearer credential (INV4)")
	}
}

// TestDebugEventsDetailTruncated pins the server-side truncation: a detail
// over the beacon bound is logged bounded (whole runes, never the tail).
func TestDebugEventsDetailTruncated(t *testing.T) {
	buf := captureLogs(t)
	long := strings.Repeat("x", beaconDetailLimit+50) + "TAIL-MARKER"
	body := fmt.Sprintf(`{"kind":"fatal","item_id":"itm_1","mode":"hls","phase":"fatal","code":"networkError","detail":%q}`, long)
	resp := doRequest(t, debugTestHandler(openAPIStore(t)), http.MethodPost, "/api/v1/debug-events", body, adminToken)
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	lines := debugLines(buf)
	if len(lines) != 1 {
		t.Fatalf("captured %d debug lines, want 1", len(lines))
	}
	if !strings.Contains(lines[0], "detail=") {
		t.Fatalf("debug line %q lacks the detail field", lines[0])
	}
	if strings.Contains(lines[0], "TAIL-MARKER") {
		t.Fatalf("debug line %q carried untruncated detail", lines[0])
	}
	if n := strings.Count(lines[0], "x"); n > beaconDetailLimit {
		t.Fatalf("logged detail run = %d chars, want <= %d", n, beaconDetailLimit)
	}
}
